import{_ as e,o as l,c as i,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-Oct-24 :: Ceph Tech Talk - Ceph at NASA","description":"","frontmatter":{"title":"2019-Oct-24 :: Ceph Tech Talk - Ceph at NASA","date":"2019-10-31T00:00:00.000Z","updated":"2019-11-01T00:00:00.000Z","tags":["Ceph","NASA","分布式存储","数据管理","存储性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-Oct-24_-_-_Ceph_Tech_Talk_-_Ceph_at_Nasa.md","filePath":"posts/2019/2019-Oct-24_-_-_Ceph_Tech_Talk_-_Ceph_at_Nasa.md","lastUpdated":1780459816000}'),a={name:"posts/2019/2019-Oct-24_-_-_Ceph_Tech_Talk_-_Ceph_at_Nasa.md"};function s(_,t,r,o,n,h){return l(),i("div",null,[...t[0]||(t[0]=[p("<p>会议纪要：</p><p><strong>会议主题</strong>： NASA大气科学数据存储与处理中的Ceph应用</p><p><strong>会议时间</strong>： 2019年10月24日</p><p><strong>参会人员</strong>： NASA大气科学团队成员、数据科学家、工程师等</p><p><strong>会议内容</strong>：</p><ul><li><strong>NASA大气科学数据存储现状</strong>： <ul><li>NASA大气科学团队负责处理和分析来自多颗卫星的原始数据，包括US-10、NOAA-20、JPSS-2等。</li><li>数据量巨大，每年产生约10PB的数据，需要高效的存储和数据处理方案。</li><li>目前主要使用Ceph作为数据存储平台，包括Rados、RGW和S3。</li><li>使用FusedFS作为POSIX文件系统层，方便科学家访问数据。</li><li>使用PostgreSQL数据库跟踪文件元数据，并确保数据完整性。</li></ul></li><li><strong>Ceph的使用情况</strong>： <ul><li>NASA团队直接使用Ceph，未使用Ceph Gateway。</li><li>使用Python绑定的库Fredo4CEPH进行数据访问。</li><li>使用PDS服务器进行数据索引和分块，提高数据处理效率。</li><li>使用Kubernetes管理Ceph集群和应用程序。</li></ul></li><li><strong>面临的挑战</strong>： <ul><li>数据量增长迅速，需要更大的存储容量和更高的性能。</li><li>Ceph集群出现了一些故障，需要改进集群稳定性和可靠性。</li><li>需要更好的数据访问方式，例如支持变量级别的数据访问。</li></ul></li><li><strong>未来计划</strong>： <ul><li>考虑迁移到BlueStore后端，提高性能。</li><li>研究使用Striper进行数据分块，提高数据访问效率。</li><li>使用upmap进行集群升级，提高集群性能和可靠性。</li><li>探索使用Geospatial Data Abstraction Library (GDAL)进行数据访问。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>继续使用Ceph作为数据存储平台，并改进集群性能和可靠性。</li><li>研究使用BlueStore后端和Striper进行数据分块。</li><li>使用upmap进行集群升级。</li><li>探索使用GDAL进行数据访问。</li></ul><p><strong>关键词</strong>： NASA、大气科学、Ceph、Rados、RGW、S3、FusedFS、PostgreSQL、BlueStore、Striper、upmap、GDAL</p>",9)])])}const c=e(a,[["render",s]]);export{u as __pageData,c as default};
